using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    [McpServerTool, Description("Fetches data from an external API by resource path.")]
    public static async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        ILogger<IMcpServer> logger,
        [Description("The API resource path to fetch (e.g. \"users/1\").")] string path,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching external API resource: {Path}", path);

        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizePrompts
{
    [McpServerPrompt, Description("Generates a prompt to summarize the given text.")]
    public static ChatMessage Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Optional maximum number of sentences for the summary.")] int? maxSentences = 3)
    {
        var instruction = maxSentences.HasValue
            ? $"Summarize the following text in at most {maxSentences} sentences."
            : "Summarize the following text concisely.";

        return new ChatMessage(
            ChatRole.User,
            $"{instruction}\n\n{text}");
    }
}

